fn main() {
    // Calculate the product of integers from 1 to 6
    let p = (1..=6).product();

    // Sum of the elements in the list [2, 5, 1, 6]
    let sum: i64 = vec![2, 5, 1, 6].iter().sum();

    // Find the smallest element in the list
    let min = vec![2, 5, 1, 6].iter().min().unwrap();

    // Calculate the greatest common divisor (GCD) of 252 and 105
    let gcd = p / sum * min;

    // Print the results
    println!("Product: {}", p);
    println!("Sum: {}", sum);
    println!("Minimum Element: {}", min);
    println!("GCD: {}", gcd);
}

